    static LlmFuncion Ok(int ti=1,int to=1) => new((m,ct)=>Task.FromResult(new LlmRespuesta("{\"respuesta\":\"x\",\"citas\":[]}", [], new LlmUso(ti,to))));
    async Task Caso(string nombre, Func<EntornoAuditoria,Task<(HttpStatusCode,string)>> f, ILlmClient? llm=null, IDictionary<string,string?>? cfg=null)
    {
        using var e = new EntornoAuditoria(llm ?? Ok(), cfg);
        try { var (c,b)=await f(e); o.WriteLine($"{nombre}: HTTP {(int)c} {b[..Math.Min(80,b.Length)]}"); } catch(Exception x){ o.WriteLine($"{nombre}: EXC {x.GetType().Name} {x.Message}"); }
        await Task.Delay(200);
        o.WriteLine("   AUD: " + e.TextoAuditoria().Replace("\n","|"));
    }
    [Fact] public async Task Todo()
    {
        await Caso("lone-surrogate", e=>e.Raw("{\"pregunta\":\"hola \\ud800\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}"));
        await Caso("lone-surrogate-id", e=>e.Raw("{\"pregunta\":\"hola\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"\\ud800\"}}"));
        await Caso("u2028", e=>e.Preguntar("a\u2028b\u0085c\rd\ne","estudiante","T-E1"));
        await Caso("vacio", e=>e.Raw(""));
        await Caso("invalidutf8", async e=>{ var r=await e.Cliente.PostAsync(EntornoAuditoria.Url,new ByteArrayContent(new byte[]{0x7b,0x22,0xff,0xfe,0x22,0x7d}){Headers={ContentType=new("application/json")}}); return (r.StatusCode,await r.Content.ReadAsStringAsync());});
        await Caso("textplain", async e=>{ var r=await e.Cliente.PostAsync(EntornoAuditoria.Url,new StringContent("{\"pregunta\":\"hola\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}",Encoding.UTF8,"text/plain")); return (r.StatusCode,await r.Content.ReadAsStringAsync());});
        await Caso("GET", async e=>{ var r=await e.Cliente.GetAsync(EntornoAuditoria.Url); return (r.StatusCode,await r.Content.ReadAsStringAsync());});
        await Caso("overflow-tokens", e=>e.Preguntar("hola","estudiante","T-E1"), Ok(int.MaxValue,int.MaxValue));
        await Caso("neg-tokens", e=>e.Preguntar("hola","estudiante","T-E1"), Ok(-5,-5));
        await Caso("llave-en-pregunta-mayus", e=>e.Preguntar(EntornoAuditoria.Llave.ToUpper()+" "+EntornoAuditoria.Llave,"estudiante","T-E1"));
        await Caso("llm-null-llamadas", e=>e.Preguntar("hola","estudiante","T-E1"), new LlmFuncion((m,ct)=>throw new NullReferenceException("x")));
        await Caso("pregunta-1001", e=>e.Preguntar(new string('a',1001),"estudiante","T-E1"));
        await Caso("pregunta-null-usuario-array", e=>e.Raw("{\"pregunta\":\"hola\",\"usuario\":[]}"));
        await Caso("body-enorme", e=>e.Raw("{\"pregunta\":\""+new string('a',40_000_000)+"\",\"usuario\":{}}"));
    }
}
